#!/usr/bin/env python3
"""
Algorithms for EML Expression Analysis

Implements verified computational methods for EML expression depth analysis,
symbolic differentiation, and bounded enumeration.

Complexity analysis:
  - deriv(e): O(|e|) time, O(|e|) new nodes
  - eml_depth(e): O(|e|) time
  - enumerate_exprs(d, s): Exponential in s, but bounded by depth d
  - check_depth_preservation: O(n * |e_max|^n) per expression, n = iteration count
"""

from __future__ import annotations
from dataclasses import dataclass
from typing import Optional, Generator
import math
from collections import Counter


# ─── EML Expression AST ───────────────────────────────────────────────

class EmlExpr:
    """Base class for EML expressions."""
    pass

@dataclass
class Var(EmlExpr):
    def __repr__(self): return "x"

@dataclass
class Const(EmlExpr):
    value: float
    def __repr__(self): return f"{self.value}"

@dataclass
class Add(EmlExpr):
    left: EmlExpr
    right: EmlExpr
    def __repr__(self): return f"({self.left} + {self.right})"

@dataclass
class Mul(EmlExpr):
    left: EmlExpr
    right: EmlExpr
    def __repr__(self): return f"({self.left} * {self.right})"

@dataclass
class Neg(EmlExpr):
    arg: EmlExpr
    def __repr__(self): return f"(-{self.arg})"

@dataclass
class Eml(EmlExpr):
    coeff: EmlExpr
    exponent: EmlExpr
    def __repr__(self): return f"eml({self.coeff}, {self.exponent})"


# ─── Core Algorithms ──────────────────────────────────────────────────

def eml_depth(expr: EmlExpr) -> int:
    """Compute EML depth.

    Time complexity: O(|expr|) — single tree traversal.
    Space complexity: O(height(expr)) for recursion stack.

    The depth counts the maximum nesting of eml operations:
      depth(var) = 0
      depth(const) = 0
      depth(add(a,b)) = max(depth(a), depth(b))
      depth(mul(a,b)) = max(depth(a), depth(b))
      depth(neg(a)) = depth(a)
      depth(eml(a,b)) = 1 + max(depth(a), depth(b))
    """
    if isinstance(expr, (Var, Const)):
        return 0
    elif isinstance(expr, (Add, Mul)):
        return max(eml_depth(expr.left), eml_depth(expr.right))
    elif isinstance(expr, Neg):
        return eml_depth(expr.arg)
    elif isinstance(expr, Eml):
        return 1 + max(eml_depth(expr.coeff), eml_depth(expr.exponent))
    raise TypeError(f"Unknown: {type(expr)}")


def expr_size(expr: EmlExpr) -> int:
    """Count nodes in the expression tree.

    Time/space: O(|expr|).
    """
    if isinstance(expr, (Var, Const)):
        return 1
    elif isinstance(expr, (Add, Mul)):
        return 1 + expr_size(expr.left) + expr_size(expr.right)
    elif isinstance(expr, Neg):
        return 1 + expr_size(expr.arg)
    elif isinstance(expr, Eml):
        return 1 + expr_size(expr.coeff) + expr_size(expr.exponent)
    return 0


def deriv(expr: EmlExpr) -> EmlExpr:
    """Symbolic differentiation with respect to x.

    Time complexity: O(|expr|) — one pass over the tree.
    Space complexity: O(|expr|) new nodes (the derivative tree shares
    subexpressions with the original in languages with sharing; here we copy).

    The derivative of eml(a,b) = a*exp(b) is:
      eml(a' + a*b', b) = (a' + a*b')*exp(b)

    This is the KEY operation: the eml shell (exp(b)) is preserved,
    and all new complexity goes into the coefficient.
    """
    if isinstance(expr, Var):
        return Const(1)
    elif isinstance(expr, Const):
        return Const(0)
    elif isinstance(expr, Add):
        return Add(deriv(expr.left), deriv(expr.right))
    elif isinstance(expr, Mul):
        return Add(Mul(deriv(expr.left), expr.right),
                   Mul(expr.left, deriv(expr.right)))
    elif isinstance(expr, Neg):
        return Neg(deriv(expr.arg))
    elif isinstance(expr, Eml):
        a, b = expr.coeff, expr.exponent
        return Eml(Add(deriv(a), Mul(a, deriv(b))), b)
    raise TypeError(f"Unknown: {type(expr)}")


def iterated_deriv(expr: EmlExpr, n: int) -> EmlExpr:
    """Compute the n-th iterated derivative.

    Time: O(n * |result|), where |result| can grow exponentially in n
    due to the product rule (size explosion).
    Depth: O(depth(expr)) — depth is preserved (our main theorem).
    """
    result = expr
    for _ in range(n):
        result = deriv(result)
    return result


def evaluate(expr: EmlExpr, x: float) -> float:
    """Evaluate an EML expression at a point.

    Time: O(|expr|).
    """
    if isinstance(expr, Var):
        return x
    elif isinstance(expr, Const):
        return expr.value
    elif isinstance(expr, Add):
        return evaluate(expr.left, x) + evaluate(expr.right, x)
    elif isinstance(expr, Mul):
        return evaluate(expr.left, x) * evaluate(expr.right, x)
    elif isinstance(expr, Neg):
        return -evaluate(expr.arg, x)
    elif isinstance(expr, Eml):
        a = evaluate(expr.coeff, x)
        b = evaluate(expr.exponent, x)
        try:
            return a * math.exp(b)
        except OverflowError:
            return float('inf') if a > 0 else float('-inf')
    raise TypeError(f"Unknown: {type(expr)}")


# ─── Enumeration Algorithm ────────────────────────────────────────────

def enumerate_exprs_by_size(max_size: int, max_depth: int,
                            constants: list[float] = [0, 1, -1]) -> list[EmlExpr]:
    """Enumerate EML expressions up to a given size and depth.

    Algorithm: Bottom-up dynamic programming by size.
    For each size s from 1 to max_size, generate all expressions of that size.

    Time complexity: O(C^max_size) where C depends on branching factor.
    Space complexity: O(|output|).

    Args:
        max_size: Maximum number of nodes in the expression tree.
        max_depth: Maximum eml-nesting depth.
        constants: List of constant values to use as leaves.

    Returns:
        List of all expressions within the bounds.
    """
    # exprs_by_size[s] = list of expressions of size exactly s
    exprs_by_size: dict[int, list[EmlExpr]] = {}

    # Size 1: leaves
    leaves = [Var()] + [Const(c) for c in constants]
    exprs_by_size[1] = leaves

    for s in range(2, max_size + 1):
        exprs_s = []
        # Neg: size = 1 + size(arg)
        if s - 1 in exprs_by_size:
            for a in exprs_by_size[s - 1]:
                exprs_s.append(Neg(a))

        # Binary operations: size = 1 + size(left) + size(right)
        for s1 in range(1, s - 1):
            s2 = s - 1 - s1
            if s1 in exprs_by_size and s2 in exprs_by_size:
                for a in exprs_by_size[s1]:
                    for b in exprs_by_size[s2]:
                        exprs_s.append(Add(a, b))
                        exprs_s.append(Mul(a, b))
                        if eml_depth(a) < max_depth and eml_depth(b) < max_depth:
                            exprs_s.append(Eml(a, b))

        exprs_by_size[s] = exprs_s

    all_exprs = []
    for s in range(1, max_size + 1):
        all_exprs.extend(exprs_by_size.get(s, []))
    return all_exprs


# ─── Depth Preservation Checker ───────────────────────────────────────

def check_depth_preservation(exprs: list[EmlExpr],
                              max_iters: int = 3) -> dict:
    """Verify depth preservation for a list of expressions.

    For each expression e, checks that
      eml_depth(deriv^n(e)) ≤ eml_depth(e)
    for n = 1, ..., max_iters.

    Returns:
        Dictionary with statistics and any counterexamples.
    """
    stats = {
        "total": len(exprs),
        "verified": 0,
        "counterexamples": [],
        "depth_drops": [],  # (expr, original_depth, deriv_depth)
        "exact_preservations": 0,
    }

    for expr in exprs:
        d0 = eml_depth(expr)
        ok = True
        dropped = False
        for n in range(1, max_iters + 1):
            try:
                dn = eml_depth(iterated_deriv(expr, n))
            except RecursionError:
                break  # expression too deep
            if dn > d0:
                stats["counterexamples"].append((str(expr), d0, n, dn))
                ok = False
                break
            if dn < d0:
                dropped = True
        if ok:
            stats["verified"] += 1
            if not dropped:
                stats["exact_preservations"] += 1
            else:
                stats["depth_drops"].append((str(expr), d0))

    return stats


# ─── Size Growth Analysis ─────────────────────────────────────────────

def analyze_size_growth(expr: EmlExpr, max_iters: int = 10) -> list[tuple[int, int, int]]:
    """Analyze how size and depth change under iterated differentiation.

    Returns:
        List of (iteration, depth, size) tuples.
    """
    results = []
    current = expr
    for n in range(max_iters + 1):
        d = eml_depth(current)
        s = expr_size(current)
        results.append((n, d, s))
        if s > 100000:
            break
        current = deriv(current)
    return results


# ─── Depth Classification ─────────────────────────────────────────────

def classify_depth_behavior(exprs: list[EmlExpr]) -> dict:
    """Classify expressions by their depth behavior under differentiation.

    Categories:
      - "constant_zero": depth 0 stays 0
      - "preserved": depth > 0, stays exactly the same after deriv
      - "dropped": depth strictly decreases after deriv
    """
    classification = Counter()
    examples = {"preserved": [], "dropped": [], "constant_zero": []}

    for expr in exprs:
        d0 = eml_depth(expr)
        d1 = eml_depth(deriv(expr))

        if d0 == 0:
            classification["constant_zero"] += 1
            if len(examples["constant_zero"]) < 3:
                examples["constant_zero"].append(str(expr))
        elif d1 == d0:
            classification["preserved"] += 1
            if len(examples["preserved"]) < 5:
                examples["preserved"].append(str(expr))
        elif d1 < d0:
            classification["dropped"] += 1
            if len(examples["dropped"]) < 5:
                examples["dropped"].append(f"{expr} : {d0} → {d1}")

    return {"counts": dict(classification), "examples": dict(examples)}


# ─── Main ──────────────────────────────────────────────────────────────

if __name__ == "__main__":
    print("EML Expression Analysis Algorithms")
    print("=" * 50)

    # Enumerate small expressions
    print("\n1. Enumerating expressions (size ≤ 5, depth ≤ 3)...")
    exprs = enumerate_exprs_by_size(max_size=5, max_depth=3)
    print(f"   Generated {len(exprs)} expressions")

    # Check depth preservation
    print("\n2. Checking depth preservation (3 iterations)...")
    stats = check_depth_preservation(exprs, max_iters=3)
    print(f"   Verified: {stats['verified']}/{stats['total']}")
    print(f"   Exact preservations: {stats['exact_preservations']}")
    print(f"   Depth drops: {len(stats['depth_drops'])}")
    print(f"   Counterexamples: {len(stats['counterexamples'])}")

    # Classify
    print("\n3. Classifying depth behavior...")
    cls = classify_depth_behavior(exprs)
    print(f"   {cls['counts']}")

    # Size growth analysis
    print("\n4. Size growth under iterated differentiation:")
    test_exprs = [
        ("x*exp(x)", Eml(Var(), Var())),
        ("exp(exp(x))", Eml(Const(1), Eml(Const(1), Var()))),
        ("x^2", Mul(Var(), Var())),
    ]
    for name, e in test_exprs:
        print(f"\n   {name}:")
        growth = analyze_size_growth(e, max_iters=6)
        for n, d, s in growth:
            print(f"     n={n}: depth={d}, size={s}")

5ab79260-acf2-4d52-bb06-d4079a160cfd.result_demo:
#!/usr/bin/env python3
"""
Real-world applications of convergent rewrite systems and the Master Theorem.

Demonstrates:
1. Boolean circuit simplification
2. Arithmetic expression optimization (compiler-style)
3. Polynomial canonical forms
4. Tropical semiring normalization
"""

from dataclasses import dataclass
from typing import Optional


# ============================================================
# Application 1: Boolean Circuit Simplification
# ============================================================

class BoolTerm:
    """Boolean expression."""
    pass

@dataclass(frozen=True)
class BVar(BoolTerm):
    name: str
    def __repr__(self): return self.name
    def size(self) -> int: return 1

@dataclass(frozen=True)
class BConst(BoolTerm):
    value: bool
    def __repr__(self): return str(self.value)
    def size(self) -> int: return 1

@dataclass(frozen=True)
class BAnd(BoolTerm):
    left: BoolTerm
    right: BoolTerm
    def __repr__(self): return f"({self.left} ∧ {self.right})"
    def size(self) -> int: return 1 + self.left.size() + self.right.size()

@dataclass(frozen=True)
class BOr(BoolTerm):
    left: BoolTerm
    right: BoolTerm
    def __repr__(self): return f"({self.left} ∨ {self.right})"
    def size(self) -> int: return 1 + self.left.size() + self.right.size()

@dataclass(frozen=True)
class BNot(BoolTerm):
    arg: BoolTerm
    def __repr__(self): return f"¬{self.arg}"
    def size(self) -> int: return 1 + self.arg.size()


def bool_simplify(term: BoolTerm) -> BoolTerm:
    """Simplify a Boolean expression using convergent rewriting rules.

    Rules (all simplifying — each reduces term size):
    1. x ∧ True → x           (identity)
    2. x ∧ False → False      (annihilation)
    3. x ∨ True → True        (annihilation)
    4. x ∨ False → x          (identity)
    5. ¬¬x → x                (double negation)
    6. x ∧ x → x              (idempotency)
    7. x ∨ x → x              (idempotency)
    8. True ∧ x → x           (identity, symmetric)
    9. False ∧ x → False      (annihilation, symmetric)
    10. True ∨ x → True
    11. False ∨ x → x

    These form a convergent rewrite system for Boolean algebra identities.
    The Master Theorem guarantees: eval(simplify(e)) = eval(e) for all
    Boolean valuations.
    """
    # Recursively simplify subterms first (innermost strategy)
    if isinstance(term, BAnd):
        left = bool_simplify(term.left)
        right = bool_simplify(term.right)
        # Apply rules
        if isinstance(right, BConst):
            if right.value:
                return left       # x ∧ True → x
            else:
                return BConst(False)  # x ∧ False → False
        if isinstance(left, BConst):
            if left.value:
                return right      # True ∧ x → x
            else:
                return BConst(False)  # False ∧ x → False
        if left == right:
            return left           # x ∧ x → x
        return BAnd(left, right)

    elif isinstance(term, BOr):
        left = bool_simplify(term.left)
        right = bool_simplify(term.right)
        if isinstance(right, BConst):
            if right.value:
                return BConst(True)   # x ∨ True → True
            else:
                return left           # x ∨ False → x
        if isinstance(left, BConst):
            if left.value:
                return BConst(True)
            else:
                return right
        if left == right:
            return left               # x ∨ x → x
        return BOr(left, right)

    elif isinstance(term, BNot):
        arg = bool_simplify(term.arg)
        if isinstance(arg, BNot):
            return arg.arg            # ¬¬x → x
        if isinstance(arg, BConst):
            return BConst(not arg.value)
        return BNot(arg)

    return term


def bool_eval(term: BoolTerm, valuation: dict[str, bool]) -> bool:
    """Evaluate a Boolean expression under a valuation."""
    if isinstance(term, BVar):
        return valuation[term.name]
    if isinstance(term, BConst):
        return term.value
    if isinstance(term, BAnd):
        return bool_eval(term.left, valuation) and bool_eval(term.right, valuation)
    if isinstance(term, BOr):
        return bool_eval(term.left, valuation) or bool_eval(term.right, valuation)
    if isinstance(term, BNot):
        return not bool_eval(term.arg, valuation)
    raise TypeError


def demo_boolean():
    """Demonstrate Boolean simplification preserving evaluation."""
    print("=" * 70)
    print("APPLICATION 1: Boolean Circuit Simplification")
    print("=" * 70)
    print()

    a, b, c = BVar("a"), BVar("b"), BVar("c")

    examples = [
        BAnd(a, BConst(True)),                          # a ∧ True
        BOr(BAnd(a, BConst(False)), b),                 # (a ∧ False) ∨ b
        BNot(BNot(BAnd(a, b))),                         # ¬¬(a ∧ b)
        BOr(BAnd(a, BOr(b, BConst(True))), BConst(False)),  # complex
        BAnd(BOr(a, a), BNot(BNot(b))),                 # (a ∨ a) ∧ ¬¬b
    ]

    for expr in examples:
        simplified = bool_simplify(expr)
        print(f"  {expr}")
        print(f"  → {simplified}")
        print(f"  Size: {expr.size()} → {simplified.size()}")

        # Verify evaluation preservation for all valuations
        all_match = True
        for av in [True, False]:
            for bv in [True, False]:
                for cv in [True, False]:
                    val = {"a": av, "b": bv, "c": cv}
                    try:
                        v1 = bool_eval(expr, val)
                        v2 = bool_eval(simplified, val)
                        if v1 != v2:
                            all_match = False
                    except KeyError:
                        pass
        print(f"  Evaluation preserved: {'✓' if all_match else '✗'}")
        print()


# ============================================================
# Application 2: Arithmetic Expression Optimization
# ============================================================

class ArithTerm:
    """Arithmetic expression in a simple compiler IR."""
    pass

@dataclass(frozen=True)
class AVar(ArithTerm):
    name: str
    def __repr__(self): return self.name
    def size(self) -> int: return 1

@dataclass(frozen=True)
class AConst(ArithTerm):
    value: int
    def __repr__(self): return str(self.value)
    def size(self) -> int: return 1

@dataclass(frozen=True)
class AAdd(ArithTerm):
    left: ArithTerm
    right: ArithTerm
    def __repr__(self): return f"({self.left} + {self.right})"
    def size(self) -> int: return 1 + self.left.size() + self.right.size()

@dataclass(frozen=True)
class AMul(ArithTerm):
    left: ArithTerm
    right: ArithTerm
    def __repr__(self): return f"({self.left} * {self.right})"
    def size(self) -> int: return 1 + self.left.size() + self.right.size()


def arith_optimize(term: ArithTerm) -> ArithTerm:
    """Optimize arithmetic expression using convergent rewrite rules.

    Rules (compiler peephole optimizations):
    1. x + 0 → x
    2. 0 + x → x
    3. x * 1 → x
    4. 1 * x → x
    5. x * 0 → 0
    6. 0 * x → 0
    7. const_fold(c1 op c2) → result

    The Master Theorem guarantees: for any interpretation of variables,
    the optimized expression evaluates the same as the original.
    """
    if isinstance(term, AAdd):
        left = arith_optimize(term.left)
        right = arith_optimize(term.right)
        # Constant folding
        if isinstance(left, AConst) and isinstance(right, AConst):
            return AConst(left.value + right.value)
        # Identity rules
        if isinstance(right, AConst) and right.value == 0:
            return left
        if isinstance(left, AConst) and left.value == 0:
            return right
        return AAdd(left, right)

    elif isinstance(term, AMul):
        left = arith_optimize(term.left)
        right = arith_optimize(term.right)
        # Constant folding
        if isinstance(left, AConst) and isinstance(right, AConst):
            return AConst(left.value * right.value)
        # Zero rules
        if isinstance(right, AConst) and right.value == 0:
            return AConst(0)
        if isinstance(left, AConst) and left.value == 0:
            return AConst(0)
        # Identity rules
        if isinstance(right, AConst) and right.value == 1:
            return left
        if isinstance(left, AConst) and left.value == 1:
            return right
        return AMul(left, right)

    return term


def arith_eval(term: ArithTerm, env: dict[str, int]) -> int:
    """Evaluate arithmetic expression."""
    if isinstance(term, AVar):
        return env[term.name]
    if isinstance(term, AConst):
        return term.value
    if isinstance(term, AAdd):
        return arith_eval(term.left, env) + arith_eval(term.right, env)
    if isinstance(term, AMul):
        return arith_eval(term.left, env) * arith_eval(term.right, env)
    raise TypeError


def demo_arithmetic():
    """Demonstrate arithmetic optimization preserving evaluation."""
    print("=" * 70)
    print("APPLICATION 2: Compiler Arithmetic Optimization")
    print("=" * 70)
    print()

    x, y = AVar("x"), AVar("y")

    examples = [
        AAdd(AMul(x, AConst(1)), AConst(0)),           # x*1 + 0
        AMul(AAdd(x, AConst(0)), AMul(AConst(1), y)),   # (x+0) * (1*y)
        AAdd(AMul(x, AConst(0)), AMul(AConst(3), AConst(4))),  # x*0 + 3*4
        AMul(AAdd(AConst(2), AConst(3)), AAdd(x, AConst(0))),  # (2+3) * (x+0)
    ]

    for expr in examples:
        optimized = arith_optimize(expr)
        print(f"  {expr}")
        print(f"  → {optimized}")
        print(f"  Size: {expr.size()} → {optimized.size()}")

        # Verify for several values
        all_match = True
        for xv in range(-3, 4):
            for yv in range(-3, 4):
                env = {"x": xv, "y": yv}
                v1 = arith_eval(expr, env)
                v2 = arith_eval(optimized, env)
                if v1 != v2:
                    all_match = False
        print(f"  Evaluation preserved: {'✓' if all_match else '✗'}")
        print()


# ============================================================
# Application 3: Tropical Semiring Normalization
# ============================================================

def demo_tropical():
    """Demonstrate tropical semiring normalization.

    The tropical semiring (R ∪ {∞}, min, +) satisfies:
    - min(a, b) = min(b, a)      (commutativity)
    - min(a, min(b, c)) = min(min(a, b), c)  (associativity)
    - a + 0 = a                  (additive identity)
    - min(a, ∞) = a              (min identity)

    Normalizing tropical expressions = convergent rewriting on these equations.
    """
    print("=" * 70)
    print("APPLICATION 3: Tropical Semiring Normalization")
    print("=" * 70)
    print()

    INF = float('inf')

    @dataclass(frozen=True)
    class TConst:
        value: float
        def __repr__(self):
            return "∞" if self.value == INF else str(self.value)

    @dataclass(frozen=True)
    class TMin:
        left: object
        right: object
        def __repr__(self): return f"min({self.left}, {self.right})"

    @dataclass(frozen=True)
    class TPlus:
        left: object
        right: object
        def __repr__(self): return f"({self.left} ⊕ {self.right})"

    def trop_eval(expr, env=None):
        if isinstance(expr, TConst):
            return expr.value
        if isinstance(expr, TMin):
            return min(trop_eval(expr.left, env), trop_eval(expr.right, env))
        if isinstance(expr, TPlus):
            return trop_eval(expr.left, env) + trop_eval(expr.right, env)
        raise TypeError

    def trop_normalize(expr):
        """Normalize tropical expression using convergent rules."""
        if isinstance(expr, TMin):
            left = trop_normalize(expr.left)
            right = trop_normalize(expr.right)
            # min(a, ∞) → a
            if isinstance(right, TConst) and right.value == INF:
                return left
            if isinstance(left, TConst) and left.value == INF:
                return right
            # min(a, a) → a
            if left == right:
                return left
            # Constant folding
            if isinstance(left, TConst) and isinstance(right, TConst):
                return TConst(min(left.value, right.value))
            return TMin(left, right)

        if isinstance(expr, TPlus):
            left = trop_normalize(expr.left)
            right = trop_normalize(expr.right)
            # a + 0 → a
            if isinstance(right, TConst) and right.value == 0:
                return left
            if isinstance(left, TConst) and left.value == 0:
                return right
            # Constant folding
            if isinstance(left, TConst) and isinstance(right, TConst):
                return TConst(left.value + right.value)
            return TPlus(left, right)

        return expr

    # Examples
    examples = [
        TMin(TConst(3), TConst(INF)),           # min(3, ∞) → 3
        TPlus(TConst(5), TConst(0)),             # 5 ⊕ 0 → 5
        TMin(TPlus(TConst(2), TConst(3)),
             TMin(TConst(INF), TConst(4))),       # min(2⊕3, min(∞,4))
        TMin(TConst(7), TMin(TConst(3), TConst(INF))),  # min(7, min(3, ∞))
    ]

    for expr in examples:
        normalized = trop_normalize(expr)
        v1 = trop_eval(expr)
        v2 = trop_eval(normalized)
        match = "✓" if v1 == v2 else "✗"
        print(f"  {expr}")
        print(f"  → {normalized}")
        print(f"  eval = {v1}, eval(nf) = {v2}  {match}")
        print()


# ============================================================
# Application 4: String Rewriting (Monoid Normalization)
# ============================================================

def demo_monoid():
    """Demonstrate string/monoid normalization.

    In a monoid with generators a, b and relation aba = ba,
