        return word

    # Example: monoid with aa → a (idempotent) and ba → ab (commutation)
    rules = [("aa", "a"), ("ba", "ab")]

    print("  Rules: aa → a, ba → ab")
    print("  (Idempotent commutative monoid normalization)")
    print()

    words = ["abba", "baab", "aabba", "babab", "aaabbb", "bbbaaab"]

    print(f"  {'Word':<15} {'Normal Form':<15} {'Steps'}")
    print("  " + "-" * 45)
    for word in words:
        nf = normalize_word(word, rules)
        print(f"  {word:<15} {nf:<15}")

    print()
    print("  The Master Theorem guarantees: for any monoid M satisfying")
    print("  aa = a and ba = ab, the evaluation of each word equals the")
    print("  evaluation of its normal form.")
    print()


