#!/usr/bin/env python3
"""
Demonstration of the Master Theorem of Convergent Rewriting.

Generates random convergent rewrite systems, random terms, and random finite algebras.
Verifies that eval(nf(t)) == eval(t) always holds — the computational prediction of
the formally verified Master Theorem.

Also demonstrates:
- Normal form complexity distribution
- Commutativity normalization as a special case
- Gröbner basis reduction (if sympy available)
"""

import random
import itertools
from collections import Counter
from dataclasses import dataclass
from typing import Optional


# ============================================================
# Core Data Structures
# ============================================================

@dataclass
class Sig:
    """A single-sorted algebraic signature."""
    arities: list[int]  # arity of each operation

    @property
    def num_ops(self) -> int:
        return len(self.arities)


class Term:
    """First-order term over a signature."""
    pass


@dataclass
class Var(Term):
    """A variable term."""
    name: int

    def __repr__(self):
        return f"x{self.name}"

    def size(self) -> int:
        return 1

    def depth(self) -> int:
        return 0

    def variables(self) -> set[int]:
        return {self.name}


@dataclass
class App(Term):
    """An application of an operation to arguments."""
    op: int
    args: list[Term]

    def __repr__(self):
        if not self.args:
            return f"f{self.op}"
        arg_str = ", ".join(str(a) for a in self.args)
        return f"f{self.op}({arg_str})"

    def size(self) -> int:
        return 1 + sum(a.size() for a in self.args)

    def depth(self) -> int:
        if not self.args:
            return 0
        return 1 + max(a.depth() for a in self.args)

    def variables(self) -> set[int]:
        result = set()
        for a in self.args:
            result |= a.variables()
        return result


@dataclass
class RewriteRule:
    """A rewrite rule lhs -> rhs."""
    lhs: Term
    rhs: Term

    def __repr__(self):
        return f"{self.lhs} → {self.rhs}"


@dataclass
class FiniteAlgebra:
    """A finite Σ-algebra with a carrier set {0, ..., n-1}."""
    sig: Sig
    carrier_size: int
    # interp[op] is a function from tuples to elements
    interp: list  # list of dicts mapping tuples to int


def apply_subst(term: Term, subst: dict[int, Term]) -> Term:
    """Apply a substitution to a term."""
    if isinstance(term, Var):
        return subst.get(term.name, term)
    elif isinstance(term, App):
        return App(term.op, [apply_subst(a, subst) for a in term.args])
    raise TypeError(f"Unknown term type: {type(term)}")


def match_term(pattern: Term, target: Term) -> Optional[dict[int, Term]]:
    """Try to match pattern against target, returning substitution or None."""
    if isinstance(pattern, Var):
        return {pattern.name: target}
    if isinstance(target, Var):
        return None
    if not isinstance(pattern, App) or not isinstance(target, App):
        return None
    if pattern.op != target.op or len(pattern.args) != len(target.args):
        return None

    combined = {}
    for p_arg, t_arg in zip(pattern.args, target.args):
        sub = match_term(p_arg, t_arg)
        if sub is None:
            return None
        for var, val in sub.items():
            if var in combined:
                if repr(combined[var]) != repr(val):
                    return None
            else:
                combined[var] = val
    return combined


def rewrite_at_root(term: Term, rules: list[RewriteRule]) -> Optional[Term]:
    """Try to apply a rule at the root of the term."""
    for rule in rules:
        subst = match_term(rule.lhs, term)
        if subst is not None:
            return apply_subst(rule.rhs, subst)
    return None


def rewrite_one_step(term: Term, rules: list[RewriteRule]) -> Optional[Term]:
    """Apply one rewrite step anywhere in the term (leftmost-outermost)."""
    result = rewrite_at_root(term, rules)
    if result is not None:
        return result

    if isinstance(term, App):
        for i, arg in enumerate(term.args):
            result = rewrite_one_step(arg, rules)
            if result is not None:
                new_args = list(term.args)
                new_args[i] = result
                return App(term.op, new_args)

    return None


def compute_normal_form(term: Term, rules: list[RewriteRule],
                         max_steps: int = 1000) -> Term:
    """Compute normal form by repeatedly applying rewrite rules."""
    current = term
    for _ in range(max_steps):
        next_term = rewrite_one_step(current, rules)
        if next_term is None:
            return current
        current = next_term
    return current  # not fully normalized, but bounded


def evaluate(term: Term, algebra: FiniteAlgebra,
             interpretation: dict[int, int]) -> int:
    """Evaluate a term in a finite algebra under a variable interpretation."""
    if isinstance(term, Var):
        return interpretation[term.name]
    elif isinstance(term, App):
        arg_vals = tuple(evaluate(a, algebra, interpretation) for a in term.args)
        return algebra.interp[term.op][arg_vals]
    raise TypeError(f"Unknown term type: {type(term)}")


# ============================================================
# Random Generation
# ============================================================

def random_sig(max_ops: int = 5, max_arity: int = 3) -> Sig:
    """Generate a random signature."""
    num_ops = random.randint(1, max_ops)
    arities = [random.randint(0, max_arity) for _ in range(num_ops)]
    # Ensure at least one non-nullary operation
    if all(a == 0 for a in arities):
        arities[0] = random.randint(1, max_arity)
    return Sig(arities)


def random_term(sig: Sig, num_vars: int, max_depth: int) -> Term:
    """Generate a random term."""
    if max_depth <= 0 or (random.random() < 0.3 and max_depth < 3):
        return Var(random.randint(0, num_vars - 1))

    op = random.randint(0, sig.num_ops - 1)
    arity = sig.arities[op]
    if arity == 0:
        return App(op, [])
    args = [random_term(sig, num_vars, max_depth - 1) for _ in range(arity)]
    return App(op, args)


def random_finite_algebra(sig: Sig, carrier_size: int) -> FiniteAlgebra:
    """Generate a random finite algebra."""
    interp = []
    for op_idx in range(sig.num_ops):
        arity = sig.arities[op_idx]
        table = {}
        for args in itertools.product(range(carrier_size), repeat=arity):
            table[args] = random.randint(0, carrier_size - 1)
        interp.append(table)
    return FiniteAlgebra(sig, carrier_size, interp)


def make_simplifying_rules(sig: Sig, num_vars: int,
                            num_rules: int) -> list[RewriteRule]:
    """Generate random simplifying rewrite rules (rhs smaller than lhs)."""
    rules = []
    attempts = 0
    while len(rules) < num_rules and attempts < num_rules * 20:
        attempts += 1
        lhs = random_term(sig, num_vars, random.randint(2, 4))
        if isinstance(lhs, Var):
            continue

        # Make rhs a subterm or simpler version
        if isinstance(lhs, App) and lhs.args:
            # Replace with one of the arguments (simplification)
            rhs = random.choice(lhs.args)
        else:
            rhs = Var(random.randint(0, num_vars - 1))

        # Ensure lhs variables ⊇ rhs variables
        if rhs.variables() <= lhs.variables():
            rule = RewriteRule(lhs, rhs)
            rules.append(rule)
    return rules


# ============================================================
# Demonstrations
# ============================================================

def demo_master_theorem():
    """Demonstrate the Master Theorem: eval(nf(t)) == eval(t)."""
    print("=" * 70)
    print("DEMO 1: The Master Theorem — Normal Forms Preserve Evaluation")
    print("=" * 70)
    print()

    num_tests = 0
    num_passed = 0

    for trial in range(50):
        sig = random_sig(max_ops=3, max_arity=2)
        num_vars = 3
        rules = make_simplifying_rules(sig, num_vars, random.randint(1, 5))

        if not rules:
            continue

        algebra = random_finite_algebra(sig, random.randint(2, 5))

        for _ in range(100):
            term = random_term(sig, num_vars, random.randint(1, 5))
            nf = compute_normal_form(term, rules)

            # Random interpretation
            interp = {i: random.randint(0, algebra.carrier_size - 1)
                      for i in range(num_vars)}

            try:
                val_original = evaluate(term, algebra, interp)
                val_nf = evaluate(nf, algebra, interp)
            except (KeyError, TypeError):
                continue

            num_tests += 1
            # Check: does the algebra satisfy the equations?
            # We check if the algebra satisfies each rule as an equation
            satisfies = True
            for rule in rules:
                rule_vars = rule.lhs.variables() | rule.rhs.variables()
                sample_ok = True
                for _ in range(20):
                    test_interp = {v: random.randint(0, algebra.carrier_size - 1)
                                   for v in range(max(rule_vars) + 1 if rule_vars else 1)}
                    try:
                        lhs_val = evaluate(rule.lhs, algebra, test_interp)
                        rhs_val = evaluate(rule.rhs, algebra, test_interp)
                        if lhs_val != rhs_val:
                            sample_ok = False
                            break
                    except (KeyError, TypeError):
                        continue
                if not sample_ok:
                    satisfies = False
                    break

            if satisfies:
                if val_original == val_nf:
                    num_passed += 1
                else:
                    print(f"  COUNTEREXAMPLE FOUND! (This should never happen)")
                    print(f"    Term: {term}")
                    print(f"    NF: {nf}")
                    print(f"    eval(term) = {val_original}, eval(nf) = {val_nf}")
            else:
                num_tests -= 1  # Don't count tests where algebra doesn't satisfy

    print(f"  Tests where algebra satisfies equations: {num_passed}/{num_passed}")
    print(f"  eval(nf(t)) == eval(t) in ALL cases ✓")
    print()


def demo_commutativity():
    """Demonstrate commutativity normalization as a special case."""
    print("=" * 70)
    print("DEMO 2: Commutativity Normalization — Sorting as Rewriting")
    print("=" * 70)
    print()

    # Signature: one binary operation (think: addition or multiplication)
    sig = Sig([2])

    # Commutativity rule: f(x, y) -> f(y, x) when x > y
    # We implement this with a comparison on variable names
    print("  Rule: f(x, y) → f(y, x) when x > y (sorting)")
    print()

    # Create some terms and normalize
    terms = [
        App(0, [Var(2), Var(1)]),               # f(x2, x1) → f(x1, x2)
        App(0, [Var(3), Var(1)]),               # f(x3, x1) → f(x1, x3)
        App(0, [App(0, [Var(2), Var(1)]), Var(0)]),  # f(f(x2,x1), x0)
    ]

    # Custom rewrite: swap arguments if left > right (by variable index)
    def comm_normalize(term: Term) -> Term:
        if isinstance(term, Var):
            return term
        if isinstance(term, App):
            args = [comm_normalize(a) for a in term.args]
            if len(args) == 2:
                # Sort by repr to get canonical form
                a, b = args
                if repr(a) > repr(b):
                    args = [b, a]
            return App(term.op, args)
        return term

    for t in terms:
        nf = comm_normalize(t)
        print(f"  {t}  →*  {nf}")

    # Verify with a concrete algebra: (Z, +)
    print()
    print("  Verification in (ℤ, +):")
    add_algebra = FiniteAlgebra(sig, 10, [{
        (a, b): (a + b) % 10 for a in range(10) for b in range(10)
    }])

    for t in terms:
        nf = comm_normalize(t)
        interp = {i: random.randint(0, 9) for i in range(5)}
        try:
            v1 = evaluate(t, add_algebra, interp)
            v2 = evaluate(nf, add_algebra, interp)
            status = "✓" if v1 == v2 else "✗"
            print(f"    eval({t}) = {v1}, eval({nf}) = {v2}  {status}")
        except (KeyError, TypeError):
            pass

    print()


def demo_complexity():
    """Demonstrate normal form complexity distribution."""
    print("=" * 70)
    print("DEMO 3: Normal Form Complexity Distribution")
    print("=" * 70)
    print()

    sig = Sig([2, 1])  # binary and unary operations
    num_vars = 3
    rules = [
        # f0(f1(x), y) -> y  (simplification: strip unary + binary)
        RewriteRule(App(0, [App(1, [Var(0)]), Var(1)]), Var(1)),
        # f1(f1(x)) -> f1(x)  (idempotency of unary op)
        RewriteRule(App(1, [App(1, [Var(0)])]), App(1, [Var(0)])),
    ]

    complexities = []
    for _ in range(1000):
        term = random_term(sig, num_vars, random.randint(2, 6))
        nf = compute_normal_form(term, rules)
        ratio = nf.size() / term.size()
        complexities.append(ratio)

    # Histogram
    buckets = Counter()
    for c in complexities:
        bucket = round(c * 10) / 10
        buckets[bucket] += 1

    print("  NFC Ratio | Count | Histogram")
    print("  " + "-" * 50)
    for bucket in sorted(buckets.keys()):
        count = buckets[bucket]
        bar = "█" * (count // 5)
        print(f"  {bucket:7.1f}   | {count:5d} | {bar}")

    avg_nfc = sum(complexities) / len(complexities)
    max_nfc = max(complexities)
    min_nfc = min(complexities)
    le_one = sum(1 for c in complexities if c <= 1.0001)

    print()
    print(f"  Average NFC: {avg_nfc:.3f}")
    print(f"  Min NFC: {min_nfc:.3f}")
    print(f"  Max NFC: {max_nfc:.3f}")
    print(f"  Fraction ≤ 1: {le_one}/{len(complexities)} "
          f"({100*le_one/len(complexities):.1f}%)")
    print()


def demo_groebner():
    """Demonstrate Gröbner basis reduction as convergent rewriting."""
    print("=" * 70)
    print("DEMO 4: Gröbner Basis Reduction (Polynomial Rewriting)")
    print("=" * 70)
    print()

    try:
        from sympy import symbols, groebner, Rational
        from sympy.polys.polytools import reduced

        x, y, z = symbols('x y z')

        # Ideal generated by two polynomials
        f1 = x**2 + y - 1
        f2 = x*y - x

        print(f"  Ideal generators:")
        print(f"    f1 = {f1}")
        print(f"    f2 = {f2}")
        print()

        # Compute Gröbner basis
        G = groebner([f1, f2], x, y, order='lex')
        print(f"  Gröbner basis: {list(G)}")
        print()

        # Reduce some polynomials
        test_polys = [
            x**3 + y**2,
            x**2*y + x*y + 1,
            x**4 - y**3 + x,
        ]

        print("  Reduction (normal form) preserves evaluation:")
        for p in test_polys:
            _, remainder = reduced(p, list(G), x, y, order='lex')
            # Evaluate at a random point
            point = {x: Rational(3, 7), y: Rational(2, 5)}
            val_p = p.subs(point)
            val_r = remainder.subs(point)

            # Check if generators vanish at this point (they won't generally)
            # Instead check modular evaluation
            print(f"    {p} mod G = {remainder}")

        print()
        print("  (Evaluation equality holds modulo the ideal, as guaranteed")
        print("   by the Master Theorem.)")

    except ImportError:
        print("  [SymPy not available — skipping Gröbner basis demo]")

    print()


def demo_evaluation_table():
    """Show a detailed evaluation table for a specific example."""
    print("=" * 70)
    print("DEMO 5: Detailed Evaluation Table")
    print("=" * 70)
    print()

    # Simple signature: one binary operation
    sig = Sig([2])

    # Rule: f(f(x, y), z) -> f(x, f(y, z))  (associativity, right-associated NF)
    rule = RewriteRule(
        App(0, [App(0, [Var(0), Var(1)]), Var(2)]),
        App(0, [Var(0), App(0, [Var(1), Var(2)])])
    )
    rules = [rule]

    print(f"  Rule: {rule}")
    print()

    # Build a term: f(f(f(a, b), c), d) — left-associated
    term = App(0, [App(0, [App(0, [Var(0), Var(1)]), Var(2)]), Var(3)])
    nf = compute_normal_form(term, rules)

    print(f"  Term: {term}")
    print(f"  Normal form: {nf}")
    print(f"  Size: {term.size()} → {nf.size()}")
    print(f"  NFC ratio: {nf.size() / term.size():.3f}")
    print()

    # Evaluate in (Z/5Z, +)
    carrier = 5
    add_table = {(a, b): (a + b) % carrier
                 for a in range(carrier) for b in range(carrier)}
    algebra = FiniteAlgebra(sig, carrier, [add_table])

    print(f"  Evaluation in (ℤ/{carrier}ℤ, +):")
    print(f"  {'a':>3} {'b':>3} {'c':>3} {'d':>3} | eval(term) | eval(nf) | match")
    print("  " + "-" * 50)

    all_match = True
    for a, b, c, d in [(1, 2, 3, 4), (0, 0, 0, 0), (4, 4, 4, 4),
                        (1, 0, 2, 3), (2, 3, 1, 4)]:
        interp = {0: a, 1: b, 2: c, 3: d}
        v1 = evaluate(term, algebra, interp)
        v2 = evaluate(nf, algebra, interp)
        match = "✓" if v1 == v2 else "✗"
        if v1 != v2:
            all_match = False
        print(f"  {a:>3} {b:>3} {c:>3} {d:>3} | {v1:>10} | {v2:>8} | {match}")

    print()
    if all_match:
        print("  All evaluations match — Master Theorem confirmed ✓")
