        "church_add_1_1": App(App(
            Lam(0, Lam(1, Lam(2, Lam(3,
                App(App(Var(0), Var(2)), App(App(Var(1), Var(2)), Var(3))))))),
            Lam(0, Lam(1, App(Var(0), Var(1))))),
            Lam(0, Lam(1, App(Var(0), Var(1))))),
    }

    for name, prog in programs.items():
