            if not is_dag:
                break

        print(f"{str(term):<40} {len(graph['vertices']):>7} "
              f"{'✓' if graph['is_complete'] else '?':>7} "
              f"{'✓' if is_dag else '✗':>5}")


if __name__ == "__main__":
    demo_reduction_graphs()
    demo_ctl_model_checking()
    demo_tight_bound()
    demo_finiteness()
    print("\n" + "=" * 60)
    print("All demonstrations complete.")
    print("=" * 60)

