#!/usr/bin/env python3
"""
algorithms.py — Algorithms for the EML Depth Hierarchy.

Implements:
1. canRepresentAtDepth: Decision procedure for tower representability
2. computeMajorant: Compute the majorant bound for an EML expression
3. enumerateEML: Enumerate all EML expressions up to a given size
4. verifyHierarchy: Numerically verify the depth hierarchy
"""

import math
import itertools
from typing import Optional, List, Tuple
from dataclasses import dataclass


# ──────────────────────────────────────────────────────────────
# Core Data Structures
# ──────────────────────────────────────────────────────────────

@dataclass
class EMLNode:
    """A node in an EML expression tree."""
    kind: str  # 'var', 'const', 'add', 'mul', 'exp', 'inv'
    value: Optional[float] = None
    children: Optional[List['EMLNode']] = None

    def eval(self, x: float) -> Optional[float]:
        """Evaluate at x. Returns None on domain error."""
        try:
            if self.kind == 'var':
                return x
            elif self.kind == 'const':
                return self.value
            elif self.kind == 'add':
                a, b = self.children[0].eval(x), self.children[1].eval(x)
                return None if a is None or b is None else a + b
            elif self.kind == 'mul':
                a, b = self.children[0].eval(x), self.children[1].eval(x)
                return None if a is None or b is None else a * b
            elif self.kind == 'exp':
                a = self.children[0].eval(x)
                return None if a is None or a > 700 else math.exp(a)
            elif self.kind == 'inv':
                a = self.children[0].eval(x)
                return None if a is None or a == 0 else 1.0 / a
        except (OverflowError, ValueError, ZeroDivisionError):
            return None
        return None

    def exp_depth(self) -> int:
        """Exponential depth (inv is free)."""
        if self.kind in ('var', 'const'):
            return 0
        elif self.kind in ('add', 'mul'):
            return max(c.exp_depth() for c in self.children)
        elif self.kind == 'exp':
            return 1 + self.children[0].exp_depth()
        elif self.kind == 'inv':
            return self.children[0].exp_depth()
        return 0

    def size(self) -> int:
        """Total number of nodes."""
        if self.children is None:
            return 1
        return 1 + sum(c.size() for c in self.children)

    def has_inv(self) -> bool:
        """Whether expression contains any inv nodes."""
        if self.kind == 'inv':
            return True
        if self.children:
            return any(c.has_inv() for c in self.children)
        return False


# ──────────────────────────────────────────────────────────────
# Algorithm 1: Decision Procedure
# ──────────────────────────────────────────────────────────────

def can_represent_at_depth(n: int, d: int) -> Tuple[bool, Optional[EMLNode]]:
    """
    Decide whether tower(n) can be represented by EML expression of expDepth ≤ d.

    Returns (result, witness):
      - If d ≥ n: returns (True, canonical_construction)
      - If d < n: returns (False, None), certified by the majorant theorem

    Time complexity: O(n) for construction, O(1) for decision
    Space complexity: O(n) for the witness tree

    Args:
        n: Tower height (tower(n, x) = exp^[n](x))
        d: Maximum allowed expDepth

    Returns:
        Tuple of (can_represent, optional_witness)
    """
    if d >= n:
        # Construct canonical tower: exp(exp(...exp(x)...))
        expr = EMLNode('var')
        for _ in range(n):
            expr = EMLNode('exp', children=[expr])
        return (True, expr)
    else:
        # Hierarchy theorem: no expression of expDepth < n represents tower(n)
        return (False, None)


# ──────────────────────────────────────────────────────────────
# Algorithm 2: Majorant Computation
# ──────────────────────────────────────────────────────────────

def compute_majorant(expr: EMLNode) -> Tuple[int, float, int]:
    """
    Compute the majorant parameters (d, C, N) such that
    |expr.eval(x)| ≤ tower(d, C * x^N) for sufficiently large x.

    This implements the structural induction from the formal proof:
    - var: (0, 1, 1)
    - const c: (0, |c|+1, 0)
    - add f g: combine majorants
    - mul f g: combine majorants
    - exp f: lift to next tower level
    - inv f: same level (using lower bound duality)

    Time complexity: O(size of expression)

    Args:
        expr: EML expression node

    Returns:
        Tuple (d, C, N) where d = expDepth, C > 0, N ≥ 0
    """
    if expr.kind == 'var':
        return (0, 1.0, 1)
    elif expr.kind == 'const':
        return (0, abs(expr.value) + 1, 0)
    elif expr.kind == 'add':
        d1, C1, N1 = compute_majorant(expr.children[0])
        d2, C2, N2 = compute_majorant(expr.children[1])
        d = max(d1, d2)
        C = C1 + C2 + 1
        N = max(N1, N2)
        return (d, C, N)
    elif expr.kind == 'mul':
        d1, C1, N1 = compute_majorant(expr.children[0])
        d2, C2, N2 = compute_majorant(expr.children[1])
        d = max(d1, d2)
        C = C1 * C2 + 1
        N = N1 + N2
        return (d, C, N)
    elif expr.kind == 'exp':
        d_inner, C_inner, N_inner = compute_majorant(expr.children[0])
        return (d_inner + 1, C_inner, N_inner)
    elif expr.kind == 'inv':
        # Inv preserves tower class (assuming non-vanishing)
        d_inner, C_inner, N_inner = compute_majorant(expr.children[0])
        return (d_inner, C_inner, N_inner)
    return (0, 1.0, 0)


# ──────────────────────────────────────────────────────────────
# Algorithm 3: Expression Enumeration
# ──────────────────────────────────────────────────────────────

def enumerate_eml(max_size: int, max_depth: int,
                  constants: List[float] = [1.0, 2.0, -1.0],
                  allow_inv: bool = True) -> List[EMLNode]:
    """
    Enumerate all EML expressions up to a given size and depth.

    Uses iterative deepening on expression size.

    Args:
        max_size: Maximum number of nodes
        max_depth: Maximum expDepth
        constants: List of constant values to use
        allow_inv: Whether to include inv nodes

    Returns:
        List of EML expressions
    """
    results = []

    def generate(size_budget: int, depth_budget: int) -> List[EMLNode]:
        if size_budget <= 0:
            return []
        if size_budget == 1:
            exprs = [EMLNode('var')]
            for c in constants:
                exprs.append(EMLNode('const', value=c))
            return exprs

        exprs = [EMLNode('var')]
        for c in constants:
            exprs.append(EMLNode('const', value=c))

        # Unary operations
        for child in generate(size_budget - 1, depth_budget):
            if depth_budget >= 1:
                exprs.append(EMLNode('exp', children=[child]))
            if allow_inv:
                exprs.append(EMLNode('inv', children=[child]))

        # Binary operations
        for s1 in range(1, size_budget - 1):
            s2 = size_budget - 1 - s1
            left_exprs = generate(s1, depth_budget)
            right_exprs = generate(s2, depth_budget)
            for left in left_exprs[:5]:  # limit to avoid explosion
                for right in right_exprs[:5]:
                    exprs.append(EMLNode('add', children=[left, right]))
                    exprs.append(EMLNode('mul', children=[left, right]))

        return exprs

    for size in range(1, max_size + 1):
        new_exprs = generate(size, max_depth)
        for expr in new_exprs:
            if expr.exp_depth() <= max_depth and expr.size() <= max_size:
                results.append(expr)

    return results


# ──────────────────────────────────────────────────────────────
# Algorithm 4: Hierarchy Verification
# ──────────────────────────────────────────────────────────────

def tower(n: int, x: float) -> float:
    """Iterated exponential tower."""
    result = x
    for _ in range(n):
        if result > 700:
            return float('inf')
        result = math.exp(result)
    return result


def verify_hierarchy(n: int, d: int, num_exprs: int = 100,
                     test_points: List[float] = None) -> dict:
    """
    Numerically verify the depth hierarchy: no expDepth-d expression matches tower(n).

    Args:
        n: Tower height
        d: Maximum expDepth (should be < n for hierarchy to hold)
        num_exprs: Number of random expressions to test
        test_points: Points at which to evaluate

    Returns:
        Dictionary with verification results
    """
    if test_points is None:
        test_points = [0.5, 1.0, 1.5, 2.0, 2.5]

    tower_vals = []
    for x in test_points:
        tv = tower(n, x)
        tower_vals.append(tv)

    import random
    best_match = float('inf')
    best_expr_str = ""
    all_mismatches = 0

    for trial in range(num_exprs):
        random.seed(trial * 7 + 13)
        # Generate random expression
        expr = _random_node(d, 5)
        if expr.exp_depth() > d:
            continue

        vals = [expr.eval(x) for x in test_points]
        if any(v is None for v in vals):
            continue

        # Compute max relative error
        max_err = 0
        for fv, tv in zip(vals, tower_vals):
            if tv != 0 and not math.isinf(tv):
                max_err = max(max_err, abs(fv - tv) / abs(tv))
            elif math.isinf(tv) and not math.isinf(fv):
                max_err = float('inf')

        if max_err < best_match:
            best_match = max_err
            best_expr_str = _node_to_str(expr)

        if max_err > 0.01:
            all_mismatches += 1

    return {
        'n': n,
        'd': d,
        'hierarchy_holds': d < n,
        'num_tested': num_exprs,
        'best_relative_error': best_match,
        'best_expression': best_expr_str,
        'all_mismatched': all_mismatches == num_exprs,
    }


def _random_node(max_depth: int, max_size: int) -> EMLNode:
    """Generate random EML node."""
    import random
    if max_size <= 1 or max_depth < 0:
        return EMLNode('var') if random.random() < 0.6 else EMLNode('const', value=random.choice([1.0, 2.0]))

    r = random.random()
    if r < 0.2:
        return EMLNode('var')
    elif r < 0.3:
        return EMLNode('const', value=random.choice([0.5, 1.0, 2.0, -1.0]))
    elif r < 0.5:
        return EMLNode('add', children=[_random_node(max_depth, max_size//2),
                                         _random_node(max_depth, max_size//2)])
    elif r < 0.7:
        return EMLNode('mul', children=[_random_node(max_depth, max_size//2),
                                         _random_node(max_depth, max_size//2)])
    elif r < 0.85 and max_depth >= 1:
        return EMLNode('exp', children=[_random_node(max_depth-1, max_size-1)])
    else:
        return EMLNode('inv', children=[_random_node(max_depth, max_size-1)])


def _node_to_str(node: EMLNode) -> str:
    if node.kind == 'var':
        return 'x'
    elif node.kind == 'const':
        return f'{node.value}'
    elif node.kind == 'add':
        return f'({_node_to_str(node.children[0])} + {_node_to_str(node.children[1])})'
    elif node.kind == 'mul':
        return f'({_node_to_str(node.children[0])} * {_node_to_str(node.children[1])})'
    elif node.kind == 'exp':
        return f'exp({_node_to_str(node.children[0])})'
    elif node.kind == 'inv':
        return f'1/({_node_to_str(node.children[0])})'
    return '?'


# ──────────────────────────────────────────────────────────────
# Main: Example Usage
# ──────────────────────────────────────────────────────────────

if __name__ == "__main__":
    print("=" * 60)
    print("EML Depth Hierarchy — Algorithms")
    print("=" * 60)
    print()

    # Algorithm 1: Decision procedure
    print("Algorithm 1: canRepresentAtDepth")
    print("-" * 40)
    for n in range(5):
        for d in range(5):
            result, witness = can_represent_at_depth(n, d)
            status = "YES" if result else "NO"
            print(f"  tower({n}) at depth {d}: {status}", end="")
            if witness:
                print(f"  witness depth={witness.exp_depth()}", end="")
            print()
    print()

    # Algorithm 2: Majorant computation
    print("Algorithm 2: Majorant Computation")
    print("-" * 40)
    test_exprs = [
        EMLNode('var'),
        EMLNode('exp', children=[EMLNode('var')]),
        EMLNode('inv', children=[EMLNode('exp', children=[EMLNode('var')])]),
        EMLNode('add', children=[
            EMLNode('exp', children=[EMLNode('var')]),
            EMLNode('inv', children=[EMLNode('var')])
        ]),
    ]
    for expr in test_exprs:
        d, C, N = compute_majorant(expr)
        print(f"  {_node_to_str(expr):30s}  →  tower({d}, {C:.1f} * x^{N})")
    print()

    # Algorithm 4: Hierarchy verification
    print("Algorithm 4: Hierarchy Verification")
    print("-" * 40)
    for n, d in [(2, 1), (3, 2), (3, 1)]:
        result = verify_hierarchy(n, d, num_exprs=200)
        print(f"  tower({n}) vs depth-{d}: hierarchy={'HOLDS' if result['hierarchy_holds'] else 'N/A'}, "
              f"best error={result['best_relative_error']:.2e}")
    print()

3877f1a1-377c-4fc4-aa03-4bc3874dedce.result_algorithms:
"""
Knuth-Bendix Completion Algorithm — Core Implementation

This module implements the Knuth-Bendix completion procedure for
equational theories, producing convergent term rewrite systems.

The algorithm takes a set of equations and a reduction ordering,
and attempts to produce a confluent, terminating rewrite system
whose equational theory matches the input.

References:
    Knuth, D. E. & Bendix, P. B. (1970). Simple Word Problems in Universal Algebras.
    Baader, F. & Nipkow, T. (1998). Term Rewriting and All That.
"""

from __future__ import annotations
from dataclasses import dataclass, field
from typing import Optional, Callable
from collections import defaultdict
import itertools


# ─────────────────────────────────────────────────────────────────────
#  Core Data Structures
# ─────────────────────────────────────────────────────────────────────

@dataclass(frozen=True)
class Term:
    """A first-order term: either a variable or a function application.

    Examples:
        >>> x = Term.var("x")
        >>> f_x = Term.fun("f", [x])
        >>> g_x_y = Term.fun("g", [x, Term.var("y")])
    """
    symbol: str
    args: tuple["Term", ...] = ()
    is_variable: bool = False

    @staticmethod
    def var(name: str) -> "Term":
        """Create a variable term."""
        return Term(symbol=name, is_variable=True)

    @staticmethod
    def fun(name: str, args: list["Term"]) -> "Term":
        """Create a function application term."""
        return Term(symbol=name, args=tuple(args), is_variable=False)

    def variables(self) -> set[str]:
        """Return the set of variable names occurring in the term."""
        if self.is_variable:
            return {self.symbol}
        result: set[str] = set()
        for arg in self.args:
            result |= arg.variables()
        return result

    def substitute(self, subst: dict[str, "Term"]) -> "Term":
        """Apply a substitution to this term."""
        if self.is_variable:
            return subst.get(self.symbol, self)
        return Term.fun(self.symbol, [a.substitute(subst) for a in self.args])

    def size(self) -> int:
        """Number of nodes in the term tree."""
        return 1 + sum(a.size() for a in self.args)

    def __str__(self) -> str:
        if self.is_variable:
            return self.symbol
        if not self.args:
            return self.symbol
        return f"{self.symbol}({', '.join(str(a) for a in self.args)})"

    def __repr__(self) -> str:
        return str(self)


@dataclass(frozen=True)
class Equation:
    """An unoriented equation between two terms."""
    lhs: Term
    rhs: Term

    def __str__(self) -> str:
        return f"{self.lhs} = {self.rhs}"


@dataclass(frozen=True)
class Rule:
    """An oriented rewrite rule: lhs → rhs."""
    lhs: Term
    rhs: Term

    def __str__(self) -> str:
        return f"{self.lhs} → {self.rhs}"


# ─────────────────────────────────────────────────────────────────────
#  Unification
# ─────────────────────────────────────────────────────────────────────

def occurs_check(var: str, term: Term) -> bool:
    """Check if variable `var` occurs in `term`."""
    if term.is_variable:
        return term.symbol == var
    return any(occurs_check(var, a) for a in term.args)


def unify(s: Term, t: Term) -> Optional[dict[str, Term]]:
    """Compute the most general unifier of two terms.

    Returns None if the terms are not unifiable.

    >>> x, y = Term.var("x"), Term.var("y")
    >>> f = lambda *a: Term.fun("f", list(a))
    >>> unify(f(x), f(y))
    {'x': y}
    """
    equations: list[tuple[Term, Term]] = [(s, t)]
    subst: dict[str, Term] = {}

    while equations:
        a, b = equations.pop()
        # Apply current substitution
        a = a.substitute(subst)
        b = b.substitute(subst)

        if a == b:
            continue
        if a.is_variable:
            if occurs_check(a.symbol, b):
                return None
            subst = {k: v.substitute({a.symbol: b}) for k, v in subst.items()}
            subst[a.symbol] = b
        elif b.is_variable:
            if occurs_check(b.symbol, a):
                return None
            subst = {k: v.substitute({b.symbol: a}) for k, v in subst.items()}
            subst[b.symbol] = a
        elif a.symbol == b.symbol and len(a.args) == len(b.args):
            equations.extend(zip(a.args, b.args))
        else:
            return None

    return subst


# ─────────────────────────────────────────────────────────────────────
#  Reduction Orderings
# ─────────────────────────────────────────────────────────────────────

def lpo(precedence: dict[str, int]) -> Callable[[Term, Term], bool]:
    """Create a Lexicographic Path Ordering (LPO) comparator.

    Returns a function `greater(s, t)` that returns True iff s > t in the LPO.

    Args:
        precedence: mapping from function symbols to precedence values (higher = greater)
    """
    def greater(s: Term, t: Term) -> bool:
        if t.is_variable:
            return not s.is_variable and t.symbol in s.variables()
        if s.is_variable:
            return False
        # Check if any argument of s is >= t
        for si in s.args:
            if si == t or greater(si, t):
                return True
        if s.symbol == t.symbol:
            # Lexicographic comparison of arguments
            for si, ti in zip(s.args, t.args):
                if si == ti:
                    continue
                if greater(si, ti):
                    return all(greater(s, tj) for tj in t.args if tj != ti)
                return False
        elif precedence.get(s.symbol, 0) > precedence.get(t.symbol, 0):
            return all(greater(s, tj) for tj in t.args)
        return False
    return greater


# ─────────────────────────────────────────────────────────────────────
#  Rewriting
# ─────────────────────────────────────────────────────────────────────

def match_term(pattern: Term, target: Term, subst: Optional[dict[str, Term]] = None) -> Optional[dict[str, Term]]:
    """One-way pattern matching: find substitution σ such that pattern[σ] = target."""
    if subst is None:
        subst = {}
    if pattern.is_variable:
        if pattern.symbol in subst:
            return subst if subst[pattern.symbol] == target else None
        subst = dict(subst)
        subst[pattern.symbol] = target
        return subst
    if target.is_variable:
        return None
    if pattern.symbol != target.symbol or len(pattern.args) != len(target.args):
        return None
    for pa, ta in zip(pattern.args, target.args):
        subst = match_term(pa, ta, subst)
        if subst is None:
            return None
    return subst


def rewrite_at_root(term: Term, rules: list[Rule]) -> Optional[Term]:
    """Try to rewrite `term` at the root using one of the rules."""
    for rule in rules:
        sigma = match_term(rule.lhs, term)
        if sigma is not None:
            return rule.rhs.substitute(sigma)
    return None


def rewrite_one_step(term: Term, rules: list[Rule]) -> Optional[Term]:
    """Apply one rewrite step at the leftmost-innermost position."""
    # Try subterms first (innermost)
    if not term.is_variable:
        for i, arg in enumerate(term.args):
            result = rewrite_one_step(arg, rules)
            if result is not None:
                new_args = list(term.args)
                new_args[i] = result
                return Term.fun(term.symbol, new_args)
    # Then try root
    return rewrite_at_root(term, rules)


def normalize(term: Term, rules: list[Rule], max_steps: int = 10000) -> Term:
    """Reduce a term to normal form using the given rules.

    Args:
        term: the term to normalize
        rules: rewrite rules to apply
        max_steps: maximum number of rewrite steps (prevents infinite loops)

    Returns:
        The normal form of the term
    """
    for _ in range(max_steps):
        result = rewrite_one_step(term, rules)
        if result is None:
            return term
        term = result
    return term  # max steps reached


# ─────────────────────────────────────────────────────────────────────
#  Critical Pairs
# ─────────────────────────────────────────────────────────────────────

def rename_variables(term: Term, suffix: str) -> Term:
    """Rename all variables in a term by adding a suffix."""
    if term.is_variable:
        return Term.var(term.symbol + suffix)
    return Term.fun(term.symbol, [rename_variables(a, suffix) for a in term.args])


def subterms_with_positions(term: Term) -> list[tuple[Term, list[int]]]:
    """Return all subterms with their positions (list of child indices)."""
    result = [(term, [])]
    if not term.is_variable:
        for i, arg in enumerate(term.args):
            for sub, pos in subterms_with_positions(arg):
                result.append((sub, [i] + pos))
    return result


def replace_at_position(term: Term, position: list[int], replacement: Term) -> Term:
    """Replace the subterm at the given position with the replacement."""
    if not position:
        return replacement
    if term.is_variable:
        raise ValueError("Invalid position for variable term")
    i = position[0]
    new_args = list(term.args)
    new_args[i] = replace_at_position(term.args[i], position[1:], replacement)
    return Term.fun(term.symbol, new_args)


def get_at_position(term: Term, position: list[int]) -> Term:
    """Get the subterm at the given position."""
    if not position:
        return term
    return get_at_position(term.args[position[0]], position[1:])


def critical_pairs(rule1: Rule, rule2: Rule) -> list[tuple[Term, Term]]:
    """Compute all critical pairs between two rules.

    A critical pair arises when the LHS of rule1 can be unified with
    a non-variable subterm of the LHS of rule2.

    Returns:
        List of (term1, term2) pairs that must be joinable for local confluence.
    """
    # Rename variables in rule1 to avoid capture
    r1_lhs = rename_variables(rule1.lhs, "'")
    r1_rhs = rename_variables(rule1.rhs, "'")

    pairs: list[tuple[Term, Term]] = []

    for subterm, pos in subterms_with_positions(rule2.lhs):
        if subterm.is_variable:
            continue
        # Skip the root position if rule1 == rule2 (trivial overlap)
        if rule1 == rule2 and not pos:
            continue

        sigma = unify(r1_lhs, subterm)
        if sigma is not None:
            # Critical pair: (rule2.rhs[σ], rule2.lhs[p ← rule1.rhs][σ])
            t1 = rule2.rhs.substitute(sigma)
            t2 = replace_at_position(rule2.lhs, pos, r1_rhs).substitute(sigma)
            pairs.append((t1, t2))

    return pairs


# ─────────────────────────────────────────────────────────────────────
#  Knuth-Bendix Completion
# ─────────────────────────────────────────────────────────────────────

@dataclass
class CompletionState:
    """State of the KB completion procedure."""
    rules: list[Rule] = field(default_factory=list)
    pending: list[Equation] = field(default_factory=list)
    step_count: int = 0

    def __str__(self) -> str:
        lines = [f"Step {self.step_count}:"]
        lines.append(f"  Rules ({len(self.rules)}):")
        for r in self.rules:
            lines.append(f"    {r}")
        lines.append(f"  Pending ({len(self.pending)}):")
        for e in self.pending:
            lines.append(f"    {e}")
        return "\n".join(lines)


@dataclass
class CompletionResult:
    """Result of KB completion."""
    terminated: bool
    rules: list[Rule]
    steps: int
    history: list[str]

    def is_convergent(self) -> bool:
        """Check if the resulting system is convergent (all critical pairs joinable)."""
        if not self.terminated:
            return False
        for r1 in self.rules:
            for r2 in self.rules:
                for cp1, cp2 in critical_pairs(r1, r2):
                    nf1 = normalize(cp1, self.rules)
                    nf2 = normalize(cp2, self.rules)
                    if nf1 != nf2:
                        return False
        return True


def kb_complete(
    equations: list[Equation],
    ordering: Callable[[Term, Term], bool],
    max_steps: int = 10000,
    verbose: bool = False,
) -> CompletionResult:
    """Run the Knuth-Bendix completion procedure.

    Args:
        equations: input equational axioms
        ordering: reduction ordering (greater function)
        max_steps: maximum number of completion steps
        verbose: if True, log each step

    Returns:
        CompletionResult with the final rewrite system

    Algorithm:
        1. Start with empty rules, all equations pending
        2. While pending equations exist:
           a. Pick an equation
           b. Normalize both sides with current rules
           c. If trivial (s = s), delete
           d. Orient into a rule (using the ordering)
           e. Compute critical pairs with all existing rules
           f. Add critical pairs to pending
        3. If pending is empty, the system is convergent
    """
    state = CompletionState(pending=list(equations))
    history: list[str] = []

    for step in range(max_steps):
        if not state.pending:
            return CompletionResult(
                terminated=True,
                rules=state.rules,
                steps=step,
                history=history,
            )

        eq = state.pending.pop(0)
        state.step_count = step

        # Normalize both sides
        lhs = normalize(eq.lhs, state.rules)
        rhs = normalize(eq.rhs, state.rules)

        if lhs == rhs:
            msg = f"Step {step}: DELETE {eq}"
            history.append(msg)
            if verbose:
                print(msg)
            continue

        # Orient the equation
        if ordering(lhs, rhs):
            new_rule = Rule(lhs, rhs)
        elif ordering(rhs, lhs):
            new_rule = Rule(rhs, lhs)
        else:
            msg = f"Step {step}: FAIL - cannot orient {lhs} = {rhs}"
            history.append(msg)
            if verbose:
                print(msg)
            return CompletionResult(
                terminated=False,
                rules=state.rules,
                steps=step,
                history=history,
            )

        msg = f"Step {step}: ORIENT {new_rule}"
        history.append(msg)
        if verbose:
            print(msg)

        # Compute critical pairs with all existing rules
        new_pairs: list[tuple[Term, Term]] = []
        for old_rule in state.rules:
            new_pairs.extend(critical_pairs(new_rule, old_rule))
            new_pairs.extend(critical_pairs(old_rule, new_rule))
        # Self-critical pairs
        new_pairs.extend(critical_pairs(new_rule, new_rule))

        state.rules.append(new_rule)

        # Add non-trivial critical pairs to pending
        for t1, t2 in new_pairs:
            nf1 = normalize(t1, state.rules)
            nf2 = normalize(t2, state.rules)
            if nf1 != nf2:
                state.pending.append(Equation(nf1, nf2))
                msg2 = f"  CP: {nf1} = {nf2}"
                history.append(msg2)
                if verbose:
                    print(msg2)

    return CompletionResult(
        terminated=False,
        rules=state.rules,
        steps=max_steps,
        history=history,
    )


# ─────────────────────────────────────────────────────────────────────
#  Convenience Constructors
# ─────────────────────────────────────────────────────────────────────

def make_var(name: str) -> Term:
    """Shorthand for creating a variable."""
    return Term.var(name)

def make_fun(name: str, *args: Term) -> Term:
    """Shorthand for creating a function application."""
    return Term.fun(name, list(args))


if __name__ == "__main__":
    # Quick test: complete the theory of a commutative, associative operation
    # with identity element
    x, y, z = make_var("x"), make_var("y"), make_var("z")
    e = make_fun("e")
    f = lambda a, b: make_fun("f", a, b)

    equations = [
        Equation(f(f(x, y), z), f(x, f(y, z))),  # associativity
        Equation(f(e, x), x),                       # left identity
        Equation(f(x, e), x),                       # right identity
    ]

    prec = {"f": 2, "e": 1}
    ordering = lpo(prec)

    result = kb_complete(equations, ordering, verbose=True)
    print(f"\nTerminated: {result.terminated}")
    print(f"Steps: {result.steps}")
    print(f"Rules: {len(result.rules)}")
    for r in result.rules:
        print(f"  {r}")
    print(f"Convergent: {result.is_convergent()}")

